//
// Copies the compiled ZK assets into public/zk so the browser can fetch them.
//
//   pnpm zk:assets
//
// FetchZkConfigProvider(baseURL) resolves each circuit as
//   <baseURL>/keys/<circuit>.prover
//   <baseURL>/keys/<circuit>.verifier
//   <baseURL>/zkir/<circuit>.bzkir
// so the layout under public/zk must mirror contracts/src/managed/verihealth.
//
// These files total ~37 MB and are gitignored, exactly like the source keys:
// they are build output, regenerated by `pnpm compact`. That means a CI or
// Vercel build that has never run the Compact toolchain will NOT have them, and
// on-chain mode will 404 when fetching a prover key. See README for the two
// supported answers (host them, or build with the toolchain available).

import { cpSync, existsSync, mkdirSync, readdirSync, rmSync, statSync } from "node:fs";
import { resolve } from "node:path";

const SOURCE = resolve(process.cwd(), "contracts/src/managed/verihealth");
const TARGET = resolve(process.cwd(), "public/zk");

function totalBytes(dir) {
  let sum = 0;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const full = resolve(dir, entry.name);
    sum += entry.isDirectory() ? totalBytes(full) : statSync(full).size;
  }
  return sum;
}

for (const sub of ["keys", "zkir"]) {
  if (existsSync(resolve(SOURCE, sub))) continue;
  console.error(
    `missing ${sub}/ under ${SOURCE}\n` +
      "Run `pnpm compact` first — the prover keys are build output and are " +
      "not committed.",
  );
  process.exit(1);
}

rmSync(TARGET, { recursive: true, force: true });
mkdirSync(TARGET, { recursive: true });

for (const sub of ["keys", "zkir"]) {
  cpSync(resolve(SOURCE, sub), resolve(TARGET, sub), { recursive: true });
}

const mb = (totalBytes(TARGET) / 1_000_000).toFixed(1);
console.log(`copied ZK assets -> public/zk (${mb} MB)`);
